// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    // fuzzed parameters: from address, v amount, and an array of one address _tos (we restrict length to 1 to make observation simple)
    function testFuzz_property(address from, uint256 v, address to) public {
        // keep to non-zero so it's a valid target in array
        vm.assume(to != address(0));
        // Deploy recorder that implements the transferFrom and approve signatures and records last selector
        Recorder r = new Recorder();

        // build single-element array for tos
        address[] memory tos = new address[](1);
        tos[0] = to;

        // call through to c.transfer; it will low-level call r (we pass r as caddress)
        // we observe which selector was actually invoked by reading the recorder's lastSelector
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract always calls selector of transferFrom(...) so recorder.lastSelector() equals that selector
        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // assert that the last selector observed by the recorder equals expected when the call succeeded
        // (this is a universal property for the reference; the mutant that uses approve(...) will record a different selector for some inputs)
        if (ok) {
            assertTrue(r.lastSelector() == expected);
        } else {
            // If the external call caused revert, still the reference contract uses transferFrom selector for the attempted call.
            // The recorder exposes whether it observed any call; if it observed one, its lastSelector must equal expected.
            // If no call reached the recorder (e.g., transfer reverted before calling), then lastSelector() == 0.
            // For the reference implementation, when the transfer attempt reached the recorder it used expected selector.
            // So assert that either no call was observed, or the observed selector equals expected.
            bytes4 sel = r.lastSelector();
            assertTrue(sel == bytes4(0) || sel == expected);
        }
    }
}

// Recorder that exposes both possible function selectors and stores the last selector seen
contract Recorder {
    bytes4 public lastSelector;
    uint public calls;

    // Implement transferFrom signature to record when it's called
    function transferFrom(address a, address b, uint256 v) external returns (bool) {
        lastSelector = msg.sig;
        calls += 1;
        return true;
    }

    // Implement approve signature to record when it's called
    function approve(address a, uint256 v) external returns (bool) {
        lastSelector = msg.sig;
        calls += 1;
        return true;
    }

    // fallback to record any other malformed calls
    fallback() external payable {
        lastSelector = msg.sig;
        calls += 1;
    }

    receive() external payable {
        lastSelector = bytes4(0);
        calls += 1;
    }
}
